# Average loss over a batch
def average_loss(predictions, truths):
    total = 0
    for p, t in zip(predictions, truths):
        total += (p - t) ** 2
    return total / len(predictions)

preds = [2.1, 3.9, 5.2]
truths = [2.0, 4.0, 5.0]
print("average loss:", average_loss(preds, truths))   # ~0.02

